"""Import the legacy SQLite database into PostgreSQL.

The two databases were built at different times, so they cannot simply be
dumped and reloaded:

* PostgreSQL already holds seeded data (20 international airlines, 40
  aircraft, 19250 seats, the role catalogue and 20 establishments) while
  SQLite holds a different airline catalogue (23 Philippine carriers). The
  primary keys collide but point at completely different rows, so overwriting
  would silently re-point every foreign key.
* ``auth_permission`` and ``django_content_type`` are regenerated by
  migrations, so their ids differ between the two databases.
* A handful of tables in SQLite no longer have a model (``packages_*``).

The transfer therefore works per table:

``COPY``
    PostgreSQL is empty, so rows keep their original primary key and any
    dependent table can reference them unchanged.

``MERGE``
    PostgreSQL already has rows, so source rows are inserted additively with
    freshly allocated primary keys. Tables listed in ``NATURAL_KEYS`` are
    matched on their natural key first, so an airline that exists in both
    databases is reused rather than duplicated. Every table that receives new
    keys is remembered, and any column that references it is rewritten --
    including tables that were themselves copied verbatim.

All foreign keys in a Django-created PostgreSQL schema are ``DEFERRABLE
INITIALLY DEFERRED``, so ``SET CONSTRAINTS ALL DEFERRED`` lets us load in any
order (including self-referencing rows such as ``airlines_flight``) and have
PostgreSQL validate the whole graph at commit.

Nothing is written unless ``--apply`` is passed.
"""
import re
import sqlite3
from pathlib import Path

from django.apps import apps
from django.conf import settings
from django.core.management.base import BaseCommand, CommandError
from django.db import connection, transaction
from django.utils import timezone

BATCH_SIZE = 5000

# Django owns these. Copying them would break auth, sessions and migration state.
SKIP_TABLES = {
    'django_migrations',
    'django_content_type',
    'auth_permission',
    'django_session',
    'django_admin_log',
    # Superseded by the current simulation system, and its ``updated_at``
    # column is NOT NULL with no default while the legacy table has no such
    # column -- there is no sensible value to give it.
    'simulation_simulationroleassignment',
}

# The two airline catalogues turned out to describe the same world: 20 of the 22
# airline names, all 67 seat layouts (with identical cabin lists), all 5
# manufacturers, all 18 aircraft types and all 40 aircraft registrations are
# present in both databases. They differ only in surrogate keys, because each
# database numbered its rows independently. Comparing primary keys therefore
# makes the catalogues look disjoint when they are not.
#
# Every airline-owned table is consequently matched on its natural key so the
# existing PostgreSQL row is reused and the imported data extends the same
# catalogue instead of forking a second one. Only genuinely new rows are
# inserted -- 'Emirates PH' and 'PAL Express', 5 seat layouts, 7 aircraft.
#
# A natural key may contain a foreign key (a cabin belongs to a seat layout).
# Foreign keys are remapped before the lookup, so the comparison is made against
# PostgreSQL values.
NATURAL_KEYS = {
    'accounts_user': ('username',),
    'airlines_airline': ('name',),
    'airlines_manufacturer': ('name',),
    'airlines_aircrafttype': ('manufacturer_id', 'model_name'),
    'airlines_aircraft': ('tail_number',),
    'airlines_seatlayout': ('name',),
    'airlines_cabin': ('seat_layout_id', 'fare_class'),
    'airlines_seat': ('seat_layout_id', 'seat_number'),
    # A fleet row is the relationship between a carrier and a type, and
    # (airline, aircraft_type) is UNIQUE, so it is matched on that pair.
    'airlines_airlinefleet': ('airline_id', 'aircraft_type_id'),
}


class Command(BaseCommand):
    help = 'Import legacy SQLite data into PostgreSQL.'

    def add_arguments(self, parser):
        parser.add_argument(
            '--source',
            default=str(Path(settings.BASE_DIR) / 'db.sqlite3'),
            help='Path to the legacy SQLite database (default: %(default)s).')
        parser.add_argument(
            '--apply',
            action='store_true',
            help='Actually write. Without this flag the command is a dry run.')

    def handle(self, *args, **options):
        apply_changes = options['apply']
        source_path = Path(options['source']).resolve()
        if not source_path.exists():
            raise CommandError(f'Source database not found: {source_path}')

        self.source = sqlite3.connect(f'file:{source_path}?mode=ro', uri=True)
        self.source.row_factory = sqlite3.Row
        self.remaps = {}
        self.orphans = []
        self.reissued = []
        self.handled = set()
        self.results = []
        self.permission_remap = {}

        self.models = {m._meta.db_table: m for m in apps.get_models() if m._meta.managed}
        source_tables = {row[0] for row in self.source.execute(
            "select name from sqlite_master where type='table' and name not like 'sqlite_%'")}

        targets = [t for t in self.ordered_tables()
                   if t in source_tables and t not in SKIP_TABLES]

        self.stdout.write(self.style.MIGRATE_HEADING(
            f'{"APPLYING" if apply_changes else "DRY RUN"}: {source_path}'))
        self.stdout.write(f'Django-managed tables skipped: {len(SKIP_TABLES)}')
        self.stdout.write(f'Tables to transfer: {len(targets)}')

        with transaction.atomic():
            with connection.cursor() as cursor:
                if apply_changes:
                    cursor.execute('SET CONSTRAINTS ALL DEFERRED')
                self.permission_remap = self.build_permission_remap(cursor)

                for table in targets:
                    self.transfer_table(cursor, table, apply_changes)

                self.transfer_m2m_tables(cursor, apply_changes)

                if apply_changes:
                    self.reset_sequences(cursor)

        self.report(source_path, apply_changes)

    # ------------------------------------------------------------------
    # discovery
    # ------------------------------------------------------------------
    def ordered_tables(self):
        """Managed models sorted so referenced tables come before referrers."""
        ordered, seen, visiting = [], set(), set()

        def visit(model):
            table = model._meta.db_table
            if table in seen or table in visiting:
                return
            visiting.add(table)
            for field in model._meta.fields:
                related = getattr(field, 'related_model', None)
                if field.is_relation and related is not None and related is not model \
                        and related._meta.managed:
                    visit(related)
            visiting.discard(table)
            seen.add(table)
            ordered.append(table)

        for model in apps.get_models():
            if model._meta.managed:
                visit(model)
        return ordered

    def forward_references(self, model):
        """{column: referenced table} for this model's own foreign keys."""
        references = {}
        for field in model._meta.fields:
            related = getattr(field, 'related_model', None)
            if field.is_relation and field.column and related is not None \
                    and related._meta.managed:
                references[field.column] = related._meta.db_table
        return references

    def postgres_columns(self, cursor, table):
        cursor.execute("""
            select column_name, is_nullable, column_default, data_type
            from information_schema.columns
            where table_schema = 'public' and table_name = %s
        """, [table])
        return {r[0]: {'nullable': r[1] == 'YES', 'default': r[2], 'type': r[3]}
                for r in cursor.fetchall()}

    def coerce(self, value, data_type):
        """SQLite has no boolean type; it stores 0/1 (and occasionally the
        strings 'true'/'false') in a column PostgreSQL treats as boolean."""
        if value is None:
            return None
        if data_type == 'boolean' and not isinstance(value, bool):
            if isinstance(value, (int, float)):
                return bool(value)
            text = str(value).strip().lower()
            if text in ('true', 't', '1', 'yes'):
                return True
            if text in ('false', 'f', '0', 'no', ''):
                return False
            return None
        return value

    # ------------------------------------------------------------------
    # transfer
    # ------------------------------------------------------------------
    def unique_columns(self, cursor, table):
        """Columns carrying a single-column UNIQUE constraint on their own."""
        cursor.execute("""
            select a.attname
            from pg_index ix
            join pg_class t on t.oid = ix.indrelid
            join lateral unnest(ix.indkey) with ordinality as k(attnum, ord) on true
            join pg_attribute a on a.attrelid = t.oid and a.attnum = k.attnum
            where ix.indisunique
              and t.relname = %s
              and t.relnamespace = 'public'::regnamespace
              and ix.indpred is null
              and ix.indnatts = 1
        """, [table])
        return {row[0] for row in cursor.fetchall()}

    def business_key_pool(self, cursor, table, column):
        """Existing values of a UNIQUE column, plus per-prefix counters so a
        replacement code keeps the same format as the value it replaces."""
        cursor.execute(f'select "{column}" from "{table}" where "{column}" is not null')
        taken = {str(row[0]) for row in cursor.fetchall()}
        return taken, {}

    def reissue_business_key(self, record, table, column, pool):
        taken, counters = pool
        value = record.get(column)
        if value is None:
            return False
        value = str(value)
        if value not in taken:
            # Claim it so a later row with the same value is reissued too.
            taken.add(value)
            return False

        match = re.match(r'^(.*?)(\d+)$', value)
        if match is None:
            # No numeric tail to increment; fall back to a plain suffix.
            suffix = 2
            candidate = f'{value}-{suffix}'
            while candidate in taken:
                suffix += 1
                candidate = f'{value}-{suffix}'
            if suffix > 100_000:
                raise CommandError(f'Could not generate a unique {table}.{column} for {value!r}')
        else:
            prefix, digits = match.group(1), match.group(2)
            if prefix not in counters:
                highest = 0
                for existing in taken:
                    other = re.match(r'^(.*?)(\d+)$', existing)
                    if other and other.group(1) == prefix:
                        highest = max(highest, int(other.group(2)))
                counters[prefix] = highest + 1
            number = counters[prefix]
            candidate = f'{prefix}{number:0{len(digits)}d}'
            while candidate in taken:
                number += 1
                candidate = f'{prefix}{number:0{len(digits)}d}'
            if number - counters[prefix] > 100_000:
                raise CommandError(f'Could not generate a unique {table}.{column} for {value!r}')
            counters[prefix] = number

        record[column] = candidate
        taken.add(candidate)
        self.reissued.append((table, column, value, candidate))
        return True

    def transfer_table(self, cursor, table, apply_changes):
        model = self.models[table]
        primary_key = model._meta.pk.column
        pg_columns = self.postgres_columns(cursor, table)
        source_columns = {r['name'] for r in self.source.execute(f'pragma table_info("{table}")')}
        shared = [c for c in pg_columns if c in source_columns]
        if primary_key not in shared:
            self.stdout.write(self.style.WARNING(f'  {table}: no shared primary key, skipped'))
            return

        missing = [c for c, meta in pg_columns.items()
                   if c not in source_columns and not meta['nullable'] and meta['default'] is None]
        now = None
        for column in missing:
            field = model._meta.get_field(column)
            if field is not None and (field.auto_now or field.auto_now_add):
                now = now or timezone.now()
                shared.append(column)

        rows = self.source.execute(f'select * from "{table}"').fetchall()
        self.handled.add(table)
        cursor.execute(f'select count(*) from "{table}"')
        existing = cursor.fetchone()[0]
        strategy = 'copy' if existing == 0 else 'merge'

        remap = self.remaps.setdefault(table, {})
        natural_columns = NATURAL_KEYS.get(table)
        references = self.forward_references(model)

        business_pools = {}
        if strategy == 'merge':
            unique = self.unique_columns(cursor, table) - {primary_key}
            for column in sorted(unique & set(pg_columns) & source_columns):
                business_pools[column] = self.business_key_pool(cursor, table, column)

        natural_index = {}
        if natural_columns:
            select = ', '.join(f'"{c}"' for c in natural_columns)
            cursor.execute(f'select {select}, "{primary_key}" from "{table}"')
            natural_index = {tuple(r[:-1]): r[-1] for r in cursor.fetchall()}

        taken = set()
        if strategy == 'copy':
            cursor.execute(f'select "{primary_key}" from "{table}"')
            taken = {r[0] for r in cursor.fetchall()}
        cursor.execute(f'select coalesce(max("{primary_key}"), 0) from "{table}"')
        next_id = cursor.fetchone()[0] + 1

        payload, reused = [], 0
        for row in rows:
            record = dict(row)
            original_id = record.get(primary_key)

            # Remap foreign keys first so a natural key that includes a
            # relationship can be compared against PostgreSQL values.
            for column, target in references.items():
                value = record.get(column)
                if value is None:
                    continue
                mapping = self.remaps.get(target)
                if mapping is None:
                    continue
                if value in mapping:
                    record[column] = mapping[value]
                else:
                    self.orphans.append((table, column, target, value))
                    record[column] = None

            if natural_columns:
                key = tuple(record.get(c) for c in natural_columns)
                match = natural_index.get(key)
                if match is not None:
                    remap[original_id] = match
                    reused += 1
                    continue

            if strategy == 'copy' and original_id not in taken:
                new_id = original_id
            else:
                new_id = next_id
                next_id += 1
            taken.add(new_id)
            remap[original_id] = new_id
            record[primary_key] = new_id

            if business_pools:
                for column, pool in business_pools.items():
                    self.reissue_business_key(record, table, column, pool)

            values = []
            for c in shared:
                if c in missing and c not in source_columns:
                    values.append(now)
                else:
                    values.append(self.coerce(record.get(c), pg_columns[c]['type']))
            payload.append(tuple(values))

        if apply_changes and payload:
            columns_sql = ', '.join(f'"{c}"' for c in shared)
            placeholders = ', '.join(['%s'] * len(shared))
            sql = f'insert into "{table}" ({columns_sql}) values ({placeholders})'
            for start in range(0, len(payload), BATCH_SIZE):
                cursor.executemany(sql, payload[start:start + BATCH_SIZE])

        self.results.append({
            'table': table,
            'strategy': strategy,
            'source': len(rows),
            'inserted': len(payload),
            'reused': reused,
        })

    # ------------------------------------------------------------------
    # many-to-many
    # ------------------------------------------------------------------
    def build_permission_remap(self, cursor):
        """Content type and permission ids differ between the two databases,
        so map them by natural key."""
        content_types = {}
        for ct_id, app_label, model in self.source.execute(
                'select id, app_label, model from django_content_type'):
            cursor.execute(
                'select id from django_content_type where app_label = %s and model = %s',
                [app_label, model])
            row = cursor.fetchone()
            if row:
                content_types[ct_id] = row[0]

        permissions = {}
        for perm_id, ct_id, codename in self.source.execute(
                'select id, content_type_id, codename from auth_permission'):
            new_ct = content_types.get(ct_id)
            if new_ct is None:
                continue
            cursor.execute(
                'select id from auth_permission where content_type_id = %s and codename = %s',
                [new_ct, codename])
            row = cursor.fetchone()
            if row:
                permissions[perm_id] = row[0]
        return permissions

    def through_models(self):
        found = {}
        for model in apps.get_models():
            if not model._meta.managed:
                continue
            for field in model._meta.local_many_to_many:
                through = field.remote_field.through
                found[through._meta.db_table] = through
        return found

    def transfer_m2m_tables(self, cursor, apply_changes):
        source_tables = {r[0] for r in self.source.execute(
            "select name from sqlite_master where type='table' and name not like 'sqlite_%'")}

        for table, through in sorted(self.through_models().items()):
            if table not in source_tables or table in self.remaps:
                continue
            references = self.forward_references(through)
            columns = list(references)
            if not columns:
                continue

            rows = self.source.execute(f'select * from "{table}"').fetchall()
            if not rows:
                continue
            self.handled.add(table)

            payload = []
            for row in rows:
                record = dict(row)
                skip = False
                for column, target in references.items():
                    value = record.get(column)
                    if value is None:
                        continue
                    if target == 'auth_permission':
                        mapped = self.permission_remap.get(value)
                    else:
                        mapping = self.remaps.get(target, {})
                        mapped = mapping.get(value)
                    if mapped is None:
                        skip = True
                        break
                    record[column] = mapped
                if skip:
                    self.orphans.append((table, 'unmatched reference', 'm2m link', None))
                    continue
                payload.append(tuple(record[c] for c in columns))

            if apply_changes and payload:
                columns_sql = ', '.join(f'"{c}"' for c in columns)
                placeholders = ', '.join(['%s'] * len(columns))
                sql = (f'insert into "{table}" ({columns_sql}) values ({placeholders}) '
                       f'on conflict do nothing')
                for start in range(0, len(payload), BATCH_SIZE):
                    cursor.executemany(sql, payload[start:start + BATCH_SIZE])

            self.results.append({
                'table': table,
                'strategy': 'm2m',
                'source': len(rows),
                'inserted': len(payload),
                'reused': 0,
            })

    # ------------------------------------------------------------------
    # sequences and reporting
    # ------------------------------------------------------------------
    def reset_sequences(self, cursor):
        for result in self.results:
            table = result['table']
            cursor.execute('select pg_get_serial_sequence(%s, %s)', [f'public.{table}', 'id'])
            sequence = cursor.fetchone()[0]
            if not sequence:
                continue
            cursor.execute(
                f'select setval(%s, coalesce(max("id"), 1), true) from "{table}"', [sequence])

    def report(self, source_path, apply_changes):
        style = self.style.SUCCESS if self.results else self.style.WARNING
        total_source = sum(r['source'] for r in self.results)
        total_inserted = sum(r['inserted'] for r in self.results)
        total_reused = sum(r['reused'] for r in self.results)

        self.stdout.write('')
        self.stdout.write(f'{"table":<44} {"strategy":<8} {"source":>8} {"inserted":>9} {"reused":>7}')
        self.stdout.write('-' * 82)
        for result in sorted(self.results, key=lambda r: r['table']):
            self.stdout.write(
                f'{result["table"]:<44} {result["strategy"]:<8} '
                f'{result["source"]:>8} {result["inserted"]:>9} {result["reused"]:>7}')
        self.stdout.write('-' * 82)
        self.stdout.write(
            f'{"TOTAL":<44} {"":<8} {total_source:>8} {total_inserted:>9} {total_reused:>7}')

        dropped = sorted(
            source_tables_of(self.source) - self.handled - SKIP_TABLES)
        if dropped:
            self.stdout.write('')
            self.stdout.write(self.style.WARNING(
                f'{len(dropped)} source table(s) had no model and were NOT transferred:'))
            for table in dropped:
                count = self.source.execute(f'select count(*) from "{table}"').fetchone()[0]
                if count:
                    self.stdout.write(f'    {count:>7}  {table}')

        if self.reissued:
            self.stdout.write('')
            self.stdout.write(self.style.WARNING(
                f'{len(self.reissued)} business code(s) reissued to stay unique:'))
            for row in self.reissued[:20]:
                self.stdout.write(f'    {row[0]}.{row[1]}: {row[2]} -> {row[3]}')
            if len(self.reissued) > 20:
                self.stdout.write(f'    ... and {len(self.reissued) - 20} more')

        if self.orphans:
            self.stdout.write('')
            self.stdout.write(self.style.WARNING(
                f'{len(self.orphans)} row(s) referenced a record that was not transferred:'))
            for row in self.orphans[:20]:
                self.stdout.write(f'    {row}')

        self.stdout.write('')
        if self.results and any(r['inserted'] for r in self.results):
            self.stdout.write(style(f'{"Applied." if apply_changes else "Dry run complete."}'))
        self.stdout.write(f'Source database left untouched: {source_path}')


def source_tables_of(source):
    return {row[0] for row in source.execute(
        "select name from sqlite_master where type='table' and name not like 'sqlite_%'")}